<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../../../CORE/Resources/js/Layouts/AdminLayout.vue';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import DataTable, { type DataTableColumn } from '../../../../../CORE/Resources/js/Components/DataTable.vue';
import EmployeeSearchSelect from '../../Components/EmployeeSearchSelect.vue';
import EmployeeMultiSearchSelect from '../../Components/EmployeeMultiSearchSelect.vue';
import type { Paginator } from '../../../../../CORE/Resources/js/types';
import { confirmDialog } from '../../../../../CORE/Resources/js/Composables/useConfirm';
import { useToast } from '../../../../../CORE/Resources/js/Composables/useToast';
const p=defineProps<{accounts:Paginator<any>;policies:any[];selectedAccount:any;ledger:any;employeeOptions:any[]}>();
const policy=useForm({name:'Standard PF',employee_contribution_percent:0,employer_contribution_percent:0,minimum_service_months:0,contribution_base:'basic',effective_from:new Date().toISOString().slice(0,10),effective_to:''});
const allocation=useForm({scope:'single',policy_id:p.policies[0]?.id??'',employee_id:'',employee_ids:[] as string[]});
function save(){policy.post(route('payroll.pf.policies.store'))}
const toast = useToast();
async function allocate(){
  // Validate before asking, so the question is never followed by a rejection of its own answer.
  if(allocation.scope==='selected'&&!allocation.employee_ids.length){toast.warning('Select at least one employee.');return}
  if(!allocation.policy_id){toast.warning('Create or select a PF policy first.');return}
  if(allocation.scope==='all'){
    const proceed = await confirmDialog({ title: 'Allocate to every eligible employee', description: 'Allocate Provident Fund accounts to every active or on-leave employee who does not already have one?', confirmLabel: 'Allocate accounts', danger: false });
    if(!proceed) return;
  }
  allocation.post(route('payroll.pf.allocate'))
}
const columns:DataTableColumn[]=[{key:'employee_id',label:'Employee'},{key:'policy',label:'Policy'},{key:'eligible_from',label:'Eligible from'},{key:'employee_balance',label:'Employee balance',align:'right'},{key:'employer_balance',label:'Employer balance',align:'right'}];
</script>
<template><AdminLayout :breadcrumbs="[{ title: 'Payroll' }, { title: 'Provident Fund' }]"><Head title="Provident Fund"/><div class="grid gap-6 xl:grid-cols-[1fr_400px]"><div><h1 class="text-xl font-bold">Provident Fund</h1><p class="text-sm text-muted-foreground">Eligible employee accounts and contribution ledger.</p><DataTable class="mt-4" route-name="payroll.pf.index" title="Provident Fund accounts" :columns="columns" :rows="accounts.data as unknown as Record<string,unknown>[]" :meta="accounts.meta"><template #cell-employee_id="{row}"><a :href="route('payroll.pf.index',{account_id:row.id})" class="text-primary hover:underline"><strong>{{row.employee_name||row.employee_id}}</strong></a><span class="block font-mono text-xs text-muted-foreground">{{row.employee_id}}</span></template><template #cell-policy="{row}">{{row.policy?.name||'—'}}</template><template #cell-employee_balance="{row}">{{Number(row.employee_balance??row.ledger_balance??0).toLocaleString()}}</template><template #cell-employer_balance="{row}">{{Number(row.employer_balance??0).toLocaleString()}}</template></DataTable><div v-if="selectedAccount" class="mt-5 rounded-xl border bg-card p-4"><h2 class="font-semibold">Ledger · {{selectedAccount.employee_name||selectedAccount.employee_id}}</h2><div class="mt-3 divide-y"><div v-for="entry in ledger?.data" :key="entry.id" class="flex justify-between py-2 text-sm"><span>{{entry.entry_date}} · {{entry.entry_type.replaceAll('_',' ')}}</span><span>{{Number(entry.amount).toLocaleString()}}</span></div></div></div></div><aside class="space-y-5"><section class="h-fit rounded-xl border bg-card p-5"><h2 class="font-semibold">Allocate PF accounts</h2><p class="mt-1 text-xs text-muted-foreground">Creates accounts only for employees who do not already have one. Existing balances and policies are left unchanged.</p><form @submit.prevent="allocate" class="mt-4 space-y-3"><div><Label>Scope</Label><select v-model="allocation.scope" class="h-10 w-full rounded-md border bg-background px-3"><option value="single">One employee</option><option value="selected">Selected employees</option><option value="all">All active / on-leave employees</option></select></div><div><Label>PF policy</Label><select v-model="allocation.policy_id" class="h-10 w-full rounded-md border bg-background px-3"><option value="">Select policy</option><option v-for="item in policies" :key="item.id" :value="item.id">{{item.name}} · {{item.employee_contribution_percent}}% / {{item.employer_contribution_percent}}%</option></select><p v-if="allocation.errors.policy_id" class="text-xs text-destructive">{{allocation.errors.policy_id}}</p></div><div v-if="allocation.scope==='single'"><Label>Employee</Label><EmployeeSearchSelect v-model="allocation.employee_id" :options="employeeOptions"/><p v-if="allocation.errors.employee_id" class="text-xs text-destructive">{{allocation.errors.employee_id}}</p></div><div v-if="allocation.scope==='selected'"><Label>Employees</Label><EmployeeMultiSearchSelect v-model="allocation.employee_ids" :options="employeeOptions"/><p v-if="allocation.errors.employee_ids" class="text-xs text-destructive">{{allocation.errors.employee_ids}}</p></div><Button :disabled="allocation.processing">Allocate accounts</Button></form></section><section class="h-fit rounded-xl border bg-card p-5"><h2 class="font-semibold">Add PF policy</h2><form @submit.prevent="save" class="mt-4 space-y-3"><div><Label>Policy name</Label><Input v-model="policy.name"/></div><div class="grid grid-cols-2 gap-3"><div><Label>Employee %</Label><Input v-model.number="policy.employee_contribution_percent" type="number" min="0" max="100" step="0.01"/></div><div><Label>Employer %</Label><Input v-model.number="policy.employer_contribution_percent" type="number" min="0" max="100" step="0.01"/></div></div><div><Label>Minimum service (months)</Label><Input v-model.number="policy.minimum_service_months" type="number" min="0"/></div><div><Label>Contribution base</Label><select v-model="policy.contribution_base" class="h-10 w-full rounded-md border bg-background px-3"><option value="basic">Basic</option><option value="gross">Gross</option><option value="house_rent">House rent</option><option value="pf_eligible">Basic + PF-eligible benefits</option></select></div><div><Label>Effective from</Label><Input v-model="policy.effective_from" type="date"/></div><Button :disabled="policy.processing">Save policy</Button><div class="mt-4 border-t pt-3"><h3 class="text-sm font-semibold">Policies</h3><p v-for="item in policies" :key="item.id" class="py-1 text-xs text-muted-foreground">{{item.name}} · {{item.employee_contribution_percent}}% / {{item.employer_contribution_percent}}%</p></div></form></section></aside></div></AdminLayout></template>
